<?php if (($articles ?? []) === []): ?><div class="help-empty"><i class="icon-document-text-outline" aria-hidden="true"></i><strong>Nenhum artigo disponível.</strong><p>Não há conteúdo publicado nesta seção.</p></div><?php else: ?><div class="help-article-list"><?php foreach ($articles as $item): ?><a href="/help/articles/<?= $this->e(rawurlencode((string) $item['slug'])) ?>"><span class="article-icon"><i class="icon-document-text-outline" aria-hidden="true"></i></span><span><strong><?= $this->e((string) $item['title']) ?></strong><?php if (!empty($item['snippet']) || !empty($item['excerpt'])): ?><small><?= $this->e((string) ($item['snippet'] ?? $item['excerpt'])) ?></small><?php endif; ?><em><?= $this->e((string) ($item['product_name'] ?? 'Moves')) ?><?php if (!empty($item['category_name'])): ?> · <?= $this->e((string) $item['category_name']) ?><?php endif; ?></em></span><i class="icon-chevron-forward-outline" aria-hidden="true"></i></a><?php endforeach; ?></div><?php endif; ?>
